using UnrealBuildTool;
using System.Collections.Generic;

public class GlyphboundTarget : TargetRules
{
	public GlyphboundTarget(TargetInfo Target) : base(Target)
	{
		Type = TargetType.Game;
		DefaultBuildSettings = BuildSettingsVersion.V8;
		IncludeOrderVersion = EngineIncludeOrderVersion.Unreal5_9;
		ExtraModuleNames.Add("Glyphbound");
	}
}
EOF
cat > Source/GlyphboundEditor.Target.cs <<'EOF'
using UnrealBuildTool;
using System.Collections.Generic;

public class GlyphboundEditorTarget : TargetRules
{
	public GlyphboundEditorTarget(TargetInfo Target) : base(Target)
	{
		Type = TargetType.Editor;
		DefaultBuildSettings = BuildSettingsVersion.V8;
		IncludeOrderVersion = EngineIncludeOrderVersion.Unreal5_9;
		ExtraModuleNames.Add("Glyphbound");
	}
}
EOF
cat > Source/Glyphbound/Glyphbound.Build.cs <<'EOF'
using UnrealBuildTool;

public class Glyphbound : ModuleRules
{
	public Glyphbound(ReadOnlyTargetRules Target) : base(Target)
	{
		PCHUsage = PCHUsageMode.UseExplicitOrSharedPCHs;

		// Every folder under Source/Glyphbound is an include root: #include "Core/GBTypes.h".
		PublicIncludePaths.Add(ModuleDirectory);

		PublicDependencyModuleNames.AddRange(new string[]
		{
			"Core", "CoreUObject", "Engine", "InputCore", "EnhancedInput",
			"Json", "JsonUtilities", "AIModule", "NavigationSystem",
			"Slate", "SlateCore", "UMG"
		});
	}
}
EOF
cat > Source/Glyphbound/Glyphbound.h <<'EOF'
#pragma once

#include "CoreMinimal.h"
EOF
cat > Source/Glyphbound/Glyphbound.cpp <<'EOF'
#include "Glyphbound.h"
#include "Modules/ModuleManager.h"

IMPLEMENT_PRIMARY_GAME_MODULE(FDefaultGameModuleImpl, Glyphbound, "Glyphbound");
EOF
