#include "GBTypes.generated.h"

GLYPHBOUND_API DECLARE_LOG_CATEGORY_EXTERN(LogGB, Log, All);

/** The two times of the map (GDD 4). */
UENUM(BlueprintType)
enum class EGBEra : uint8
{
	Past,
	Future
};

