// The stat system: base values from data + stacked modifiers. One per actor that has tunable numbers.
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Data/GBDataTypes.h"
#include "GBStatsComponent.generated.h"

/**
 * How every tunable number is read in the game:
 *   value = Evaluate(Key, Base)  ->  (Base + sum of Add) * product of Multiply, or the last Override if any.
 * - Actor stats (MoveSpeed, MaxHealth...): base values are stored here with SetBaseStats and read with GetStat.
 * - Weapon and spell numbers: the base comes from the weapon / spell definition and the caller passes the
 *   modifier keys ("Weapon.<Id>.<Stat>", "Weapon.All.<Stat>", "Spell.<Id>.<Param>", "Spell.All.<Param>").
 * Modifiers are added in groups identified by a Source name ("Skill.FireballDamage", "Armor", "Effect.Slow#3",
 * "Passive.DoubleJump"), and removed by that same name. Skill trees, armor, status effects, air passives and
 * the weapon enchant are all just sources of modifiers.
 */
UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBStatsComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBStatsComponent();

	/** The stats component of an actor, or null. */
	static UGBStatsComponent* Find(const AActor* Actor);

	/** Replaces the base stats (from Player.json / Enemies.json) and broadcasts OnStatsChanged. */
	void SetBaseStats(const TMap<FName, float>& InBaseStats);
	void SetBaseStat(FName Stat, float Value);
	bool HasBaseStat(FName Stat) const;

	/** Base stat of this actor with its modifiers applied. DefaultValue is the base when the stat is not in the data. */
	UFUNCTION(BlueprintCallable, Category = "Glyphbound|Stats")
	float GetStat(FName Stat, float DefaultValue = 0.f) const;

	/** Applies the modifiers registered under Key to an external base value. */
	float Evaluate(FName Key, float Base) const;

	/** Same, merging the modifiers of several keys (e.g. "Weapon.Pistol.Damage" and "Weapon.All.Damage"). */
	float EvaluateKeys(TConstArrayView<FName> Keys, float Base) const;

	/** Adds a group of modifiers. Calling it again with the same Source replaces that source's modifiers. */
	void AddModifiers(FName Source, TConstArrayView<FGBModifierDef> Modifiers, float ValueScale = 1.f);
	void RemoveModifiers(FName Source);
	bool HasModifierSource(FName Source) const;

	/** Pure math, also used by the tests: applies Modifiers (already filtered to one stat) to Base. */
	static float ApplyModifiers(float Base, TConstArrayView<FGBModifierDef> Modifiers);

	/** Base stats or modifiers changed: re-read whatever you cached (walk speed, max jumps...). */
	FSimpleMulticastDelegate OnStatsChanged;

protected:
	struct FSourcedModifier
	{
		FName Source;
		FGBModifierDef Modifier;
	};

	UPROPERTY()
	TMap<FName, float> BaseStats;

	TArray<FSourcedModifier> ActiveModifiers;
};

// Health and mana with regeneration, team, damage intake and death. Used by the player and by enemies.
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Core/GBTypes.h"
#include "GBAttributeComponent.generated.h"

class UGBStatsComponent;

DECLARE_MULTICAST_DELEGATE_TwoParams(FGBOnAttributeChanged, float /*NewValue*/, float /*MaxValue*/);
DECLARE_MULTICAST_DELEGATE_TwoParams(FGBOnDamaged, const FGBDamageInfo& /*Info*/, float /*ActualDamage*/);
DECLARE_MULTICAST_DELEGATE_OneParam(FGBOnDeath, const FGBDamageInfo& /*KillingBlow*/);
/** Lets shields, blocks and buffs change a hit before it lands (set Info.Amount to 0 to cancel it). */
DECLARE_MULTICAST_DELEGATE_OneParam(FGBOnModifyIncomingDamage, FGBDamageInfo& /*InOutInfo*/);

/**
 * Reads its numbers from the owner's UGBStatsComponent (MaxHealth, HealthRegen, HealthRegenDelay, MaxMana,
 * ManaRegen, ManaRegenDelay, DamageTaken), so modifiers change them live. Regeneration is automatic (GDD 6):
 * it starts HealthRegenDelay seconds after the last damage / ManaRegenDelay seconds after the last spend.
 */
UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBAttributeComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBAttributeComponent();

	/** The attribute component of an actor, or null. */
	static UGBAttributeComponent* Find(const AActor* Actor);

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Attributes")
	EGBTeam Team = EGBTeam::Neutral;

	/** Call once the owner's base stats are set: fills health and mana to their maximum. */
	void InitializeFromStats();

	float GetHealth() const { return Health; }
	float GetMaxHealth() const;
	float GetMana() const { return Mana; }
	float GetMaxMana() const;
	bool IsDead() const { return bDead; }

	/** Runs OnModifyIncomingDamage, applies the DamageTaken stat, subtracts health, fires OnDamaged / OnDeath. Returns the damage really dealt. */
	float ApplyDamage(const FGBDamageInfo& Info);

	void Heal(float Amount);
	void RestoreMana(float Amount);

	bool HasMana(float Amount) const;
	/** Spends mana if there is enough; false and nothing spent otherwise. Restarts the mana regen delay. */
	bool SpendMana(float Amount);

	/** Full health and mana (era travel, GDD 4). Also revives. */
	void RestoreAll();

	/** For checkpoints and snapshots. Clamped to the current maximums. */
	void SetHealthAndMana(float NewHealth, float NewMana);

	/** While true, ApplyDamage does nothing (dash i-frames, cutscenes, respawn). */
	void SetInvulnerable(bool bInInvulnerable) { bInvulnerable = bInInvulnerable; }
	bool IsInvulnerable() const { return bInvulnerable; }

	/** Pure regen step, also used by the tests: the new value after DeltaTime, given the time since the last damage/spend. */
	static float StepRegen(float Current, float Max, float RegenPerSecond, float RegenDelay, float TimeSinceLastLoss, float DeltaTime);

	FGBOnAttributeChanged OnHealthChanged;
	FGBOnAttributeChanged OnManaChanged;
	FGBOnDamaged OnDamaged;
	FGBOnDeath OnDeath;
	FGBOnModifyIncomingDamage OnModifyIncomingDamage;

	virtual void TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction) override;

protected:
	virtual void BeginPlay() override;

	UGBStatsComponent* GetStats() const;

	float Health = 0.f;
	float Mana = 0.f;
	float TimeSinceDamage = 1000.f;
	float TimeSinceManaSpend = 1000.f;
	bool bDead = false;
	bool bInvulnerable = false;
};

// Timed effects defined in StatusEffects.json: slow, burn, potions, injection, weapon enchant buffs...
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Core/GBTypes.h"
#include "GBStatusEffectComponent.generated.h"

/** A running effect, exposed for the HUD. */
struct FGBActiveStatusEffect
{
	FName EffectId = NAME_None;
	float TimeRemaining = 0.f;
	float TotalDuration = 0.f;
	float TimeToNextTick = 0.f;
	float StrengthScale = 1.f;
	int32 Stacks = 1;
	TWeakObjectPtr<AActor> Instigator;
	/** Source name used for its modifiers in UGBStatsComponent. */
	FName ModifierSource = NAME_None;
};

/**
 * Applies data-defined effects to its owner:
 *  - instant health / mana on start (injection),
 *  - periodic health / mana (potions over time, burn),
 *  - stat modifiers while active (slow, enchant), through the owner's UGBStatsComponent.
 * Periodic damage goes through UGBCombatLibrary::DealDamage, so shields and DamageTaken apply.
 */
UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBStatusEffectComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBStatusEffectComponent();

	static UGBStatusEffectComponent* Find(const AActor* Actor);

	/**
	 * Starts (or refreshes / stacks, as the definition says) an effect.
	 * DurationScale multiplies the definition's Duration; StrengthScale multiplies the per-tick and instant amounts
	 * and the Add part of its modifiers (Multiply modifiers are scaled around 1: 1 + (Value - 1) * StrengthScale).
	 * Returns false if the id is unknown.
	 */
	bool ApplyEffect(FName EffectId, AActor* Instigator, float DurationScale = 1.f, float StrengthScale = 1.f);

	void RemoveEffect(FName EffectId);
	void RemoveAllEffects();
	bool HasEffect(FName EffectId) const;
	float GetTimeRemaining(FName EffectId) const;

	const TArray<FGBActiveStatusEffect>& GetActiveEffects() const { return ActiveEffects; }

	FSimpleMulticastDelegate OnEffectsChanged;

	virtual void TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction) override;

protected:
	TArray<FGBActiveStatusEffect> ActiveEffects;
	int32 NextEffectSerial = 1;
};

// The one place where damage is dealt, plus the pure combat math (unit-tested).
#pragma once

#include "CoreMinimal.h"
#include "Kismet/BlueprintFunctionLibrary.h"
#include "Core/GBTypes.h"
#include "GBCombatLibrary.generated.h"

UCLASS()
class GLYPHBOUND_API UGBCombatLibrary : public UBlueprintFunctionLibrary
{
	GENERATED_BODY()

public:
	/**
	 * Deals one hit to Target (needs a UGBAttributeComponent; otherwise returns 0).
	 * Applies the instigator's DamageDealt stat, skips friendly fire (same team, unless bAllowFriendlyFire),
	 * forwards to UGBAttributeComponent::ApplyDamage, and applies Info.OnHitEffect if the target has a
	 * UGBStatusEffectComponent and the hit was not cancelled. Returns the damage really dealt.
	 */
	static float DealDamage(AActor* Target, const FGBDamageInfo& Info, bool bAllowFriendlyFire = false);

	/**
	 * Damages every hostile actor with attributes whose origin is within Radius of Origin (sphere overlap on pawns
	 * and world dynamic). With bLinearFalloff the damage goes from full at the center to 0 at the edge.
	 * Info.HitLocation / HitDirection are filled per target. Returns how many actors were damaged.
	 */
	static int32 DealRadialDamage(const UObject* WorldContextObject, const FVector& Origin, float Radius, const FGBDamageInfo& Info,
		TConstArrayView<AActor*> IgnoreActors, bool bLinearFalloff = false);

	static EGBTeam GetTeam(const AActor* Actor);

	/** Player vs Enemy are hostile; Neutral is hostile to nobody. */
	static bool AreHostile(const AActor* A, const AActor* B);
	static bool AreTeamsHostile(EGBTeam A, EGBTeam B);

	static bool IsAlive(const AActor* Actor);

	// ---- Pure math (tests in Tests/) ----

	/**
	 * Damage multiplier by distance (GDD 5 "damage by distance"): NearMult up to FalloffStart, FarMult from
	 * FalloffEnd on, linear in between. FalloffEnd <= FalloffStart means a hard step at FalloffStart.
	 */
	static float DistanceFalloffMultiplier(float Distance, float FalloffStart, float FalloffEnd, float NearMult, float FarMult);

	/**
	 * Headshot rule for sprites and capsules (GDD 3): the head is the top HeadFraction of the body.
	 * FeetZ = bottom of the body, BodyHeight = full height, HitZ = world Z of the hit.
	 */
	static bool IsHeadshot(float HitZ, float FeetZ, float BodyHeight, float HeadFraction);

	/** A random direction inside a cone of SpreadDegrees (full angle = 2 * half-angle... SpreadDegrees is the half-angle). */
	static FVector ApplySpread(const FVector& Direction, float SpreadHalfAngleDegrees, FRandomStream& Random);
};

