// Base class of everything the player holds: staffs, guns, the elemental sword.
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "Core/GBTypes.h"
#include "Data/GBDataTypes.h"
#include "GBHeldItem.generated.h"

class AGBPlayerCharacter;
class UGBStatsComponent;

/** Ammo of one weapon (GDD 8: fixed spare magazines, each with a fixed number of bullets). Zero for staffs and swords. */
USTRUCT(BlueprintType)
struct GLYPHBOUND_API FGBAmmoState
{
	GENERATED_BODY()

	UPROPERTY() int32 InMagazine = 0;
	UPROPERTY() int32 SpareMagazines = 0;
};

/**
 * A held item is an actor attached to the player's view. It is created from a FGBWeaponDefinition (Weapons.json)
 * by UGBEquipmentComponent and reads every number through GetStat(), so skill-tree and enchant modifiers apply
 * (keys "Weapon.<Id>.<Stat>" and "Weapon.All.<Stat>" on the owner's UGBStatsComponent).
 * Subclasses: AGBStaff (basic magic attack), AGBGun (shoot, aim, reload), AGBSword (melee).
 */
UCLASS(Abstract)
class GLYPHBOUND_API AGBHeldItem : public AActor
{
	GENERATED_BODY()

public:
	AGBHeldItem();

	/** Called once right after spawn. */
	virtual void InitFromDefinition(const FGBWeaponDefinition& Definition, AGBPlayerCharacter* InOwner);

	FName GetWeaponId() const { return WeaponId; }
	EGBHeldSlot GetSlot() const { return Slot; }
	/** May differ from the definition (the sword takes the gem's element). */
	EGBElement GetElement() const { return Element; }
	void SetElement(EGBElement InElement) { Element = InElement; }
	/** The definition, looked up by id each time (never cached across frames). May be null after a data reload that removed it. */
	const FGBWeaponDefinition* GetDefinition() const;
	FString GetDisplayName() const;

	/** Weapon stat with modifiers applied. */
	float GetStat(FName Stat, float DefaultValue = 0.f) const;

	// ---- Input, routed by the player character ----
	virtual void StartPrimary() {}
	virtual void StopPrimary() {}
	virtual void StartSecondary() {}
	virtual void StopSecondary() {}
	virtual void Reload() {}

	/** Brought up / put away (the actor stays alive while not held, hidden). */
	virtual void OnEquipped();
	virtual void OnUnequipped();
	bool IsEquipped() const { return bEquipped; }

	// ---- Ammo (meaningful for guns; staffs and swords return false / zero) ----
	virtual bool UsesAmmo() const { return false; }
	virtual FGBAmmoState GetAmmo() const { return FGBAmmoState(); }
	virtual void SetAmmo(const FGBAmmoState& InAmmo) {}
	/** Full magazine and full spare magazines (era travel, GDD 8). */
	virtual void RefillAmmo() {}
	/** Adds spare magazines up to the SpareMagazines stat. Returns how many were really added. */
	virtual int32 AddSpareMagazines(int32 Count) { return 0; }
	virtual bool IsReloading() const { return false; }
	virtual bool IsAiming() const { return false; }
	/** 0..1 progress of the current reload, for the HUD. */
	virtual float GetReloadProgress() const { return 0.f; }

	/** HUD skin this item asks for (GDD 13): staff and sword = Rpg90s, gun = Cyberpunk. */
	virtual EGBHudSkin GetHudSkin() const;

	/** Seconds since the last primary attack, for HUD hand animation. */
	float GetTimeSinceLastAttack() const;

protected:
	AGBPlayerCharacter* GetPlayerOwner() const { return PlayerOwner.Get(); }
	UGBStatsComponent* GetOwnerStats() const;

	/** Builds the item's damage for one hit: Damage stat, element, instigator, SourceId = WeaponId, OnHitEffect from Strings. */
	FGBDamageInfo MakeDamageInfo() const;

	UPROPERTY(VisibleAnywhere) TObjectPtr<USceneComponent> Root;

	UPROPERTY() FName WeaponId = NAME_None;
	UPROPERTY() EGBHeldSlot Slot = EGBHeldSlot::Gun;
	UPROPERTY() EGBElement Element = EGBElement::Physical;
	TWeakObjectPtr<AGBPlayerCharacter> PlayerOwner;
	bool bEquipped = false;
	double LastAttackTime = -1000.0;
};

// The player's held slots: one staff, one gun, and the elemental sword once obtained (GDD 8).
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Core/GBTypes.h"
#include "Weapons/GBHeldItem.h"
#include "GBEquipmentComponent.generated.h"

struct FGBPlayerSnapshot;

DECLARE_MULTICAST_DELEGATE_OneParam(FGBOnActiveItemChanged, AGBHeldItem* /*NewActive (may be null)*/);

UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBEquipmentComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBEquipmentComponent();

	/**
	 * Gives a weapon from Weapons.json. It goes to the slot its definition says; a weapon already in that slot is
	 * replaced (and, if bDropOld, left on the floor as a pickup - provisional rule for swapping guns and staffs).
	 * bAutoSwitch brings it up immediately. Returns the new item, or null if the id is unknown.
	 */
	AGBHeldItem* GiveWeapon(FName WeaponId, bool bAutoSwitch = true, bool bDropOld = true);

	bool HasWeaponInSlot(EGBHeldSlot Slot) const;
	AGBHeldItem* GetItemInSlot(EGBHeldSlot Slot) const;

	AGBHeldItem* GetActiveItem() const;
	EGBHeldSlot GetActiveSlot() const { return ActiveSlot; }
	bool IsHoldingStaff() const;
	bool IsHoldingGun() const;

	/** False if the slot is empty or switching is locked. */
	bool SwitchTo(EGBHeldSlot Slot);
	/** Next / previous filled slot (mouse wheel, Alt, D-pad up). */
	void CycleSlot(int32 Direction = 1);

	/** While locked (QTE running, cutscene), SwitchTo and CycleSlot do nothing. */
	void SetSwitchLocked(bool bLocked) { bSwitchLocked = bLocked; }

	/** Refills every gun (era travel). */
	void RefillAllAmmo();
	/** Adds spare magazines to the gun in the gun slot. Returns how many were added. */
	int32 AddSpareMagazines(int32 Count);

	/** HUD skin asked by the active item; Rpg90s when the hands are empty. */
	EGBHudSkin GetHudSkin() const;

	void SaveToSnapshot(FGBPlayerSnapshot& Snapshot) const;
	void LoadFromSnapshot(const FGBPlayerSnapshot& Snapshot);

	FGBOnActiveItemChanged OnActiveItemChanged;
	/** Any change of weapons or ammo that the HUD should redraw. */
	FSimpleMulticastDelegate OnEquipmentChanged;

protected:
	UPROPERTY() TMap<EGBHeldSlot, TObjectPtr<AGBHeldItem>> Items;
	EGBHeldSlot ActiveSlot = EGBHeldSlot::Staff;
	bool bSwitchLocked = false;
};

// A resolved spell cast and the pure functions that resolve it (unit-tested).
#pragma once

#include "CoreMinimal.h"
#include "Core/GBTypes.h"
#include "Data/GBDataTypes.h"
#include "GBSpellTypes.generated.h"

class UGBStatsComponent;

/**
 * One cast, with every parameter already turned into a number:
 *   data (Spells.json Params) -> QTE scaling (Power / Reach) -> modifiers (skill tree, gear) -> Values.
 * Spell behaviors read only this struct, never the JSON, so any parameter can be retuned or re-tagged in data.
 */
USTRUCT(BlueprintType)
struct GLYPHBOUND_API FGBSpellCast
{
	GENERATED_BODY()

	UPROPERTY() FName SpellId = NAME_None;
	UPROPERTY() EGBElement Element = EGBElement::Arcane;
	/** QTE part 1 score, 0..1. */
	UPROPERTY() float Power = 0.f;
	/** QTE part 2 score, 0..1. */
	UPROPERTY() float Reach = 0.f;
	/** False when the QTE is off: every parameter used its Base value. */
	UPROPERTY() bool bUsedQTE = false;
	UPROPERTY() TMap<FName, float> Values;
	UPROPERTY() TMap<FName, FString> Strings;
	UPROPERTY() TObjectPtr<AActor> Caster = nullptr;
	/** Where the cast starts (the caster's aim origin) and where it points. */
	UPROPERTY() FVector Origin = FVector::ZeroVector;
	UPROPERTY() FVector Direction = FVector::ForwardVector;

	float Get(FName Param, float DefaultValue = 0.f) const;
	bool Has(FName Param) const;
	FString GetString(FName Key, const FString& DefaultValue = FString()) const;

	/** A hit of this spell: Amount = Get(AmountParam), spell element, caster as instigator, SourceId, OnHitEffect + its scales. */
	FGBDamageInfo MakeDamageInfo(FName AmountParam, AActor* Causer = nullptr) const;
};

/** Why a cast did not happen (HUD feedback). */
UENUM(BlueprintType)
enum class EGBCastFailReason : uint8
{
	None,
	UnknownSpell,
	EmptySlot,
	NotKnown,
	WrongHeldItem,
	OnCooldown,
	NotEnoughMana,
	Busy,
	QTEFailed
};

namespace GBSpell
{
	/**
	 * Resolves every parameter of Definition. Stats may be null (no modifiers).
	 * Modifier keys per parameter: "Spell.<Id>.<Param>" and "Spell.All.<Param>".
	 */
	GLYPHBOUND_API FGBSpellCast ResolveCast(const FGBSpellDefinition& Definition, float Power, float Reach, bool bUseQTE, const UGBStatsComponent* Stats);

	/** One parameter, same rules; DefaultValue when the spell does not define it. */
	GLYPHBOUND_API float ResolveParam(const FGBSpellDefinition& Definition, FName Param, float Power, float Reach, bool bUseQTE, const UGBStatsComponent* Stats, float DefaultValue = 0.f);
}

// Base class of the spell behaviors. A spell in Spells.json names one of these classes in "ActorClass".
#pragma once

#include "CoreMinimal.h"
#include "GameFramework/Actor.h"
#include "Spells/GBSpellTypes.h"
#include "GBSpellActor.generated.h"

/**
 * A behavior is spawned by UGBSpellbookComponent at the cast origin, receives the resolved FGBSpellCast in
 * InitSpell, and does its thing using only Cast.Get("<Param>") values. It destroys itself when done.
 *
 * Behaviors (each documents the params and strings it reads at the top of its header):
 *   AGBSpell_Projectile  fireball, lightning bolt      (launches an AGBProjectile)
 *   AGBSpell_Wall        fire wall, ice wall           (a wall in front of the caster; blocks and/or burns)
 *   AGBSpell_Zone        ice floor                     (ground area that applies an effect / damage over time)
 *   AGBSpell_Trap        lightning rune                (arms on the ground, triggers when an enemy steps on it)
 *   AGBSpell_Orb         static-electricity ball       (moves forward and damages everything around it)
 *   AGBSpell_Beam        flamethrower                  (sustained cone from the caster's aim)
 *   AGBSpell_Shield      ice shield                    (sustained frontal block on the caster)
 *   AGBSpell_Enchant     weapon enchant                (timed status effect on the caster that buffs the gun)
 * To add a spell that fits an existing behavior: only add an entry to Spells.json.
 * To add a new behavior: subclass this, document its params, and reference the class from Spells.json.
 */
UCLASS(Abstract)
class GLYPHBOUND_API AGBSpellActor : public AActor
{
	GENERATED_BODY()

public:
	AGBSpellActor();

	/** Called once, right after spawn. Subclasses call Super first (it stores Cast). */
	virtual void InitSpell(const FGBSpellCast& InCast);

	/** Sustained spells: the cast input was pressed again, the caster switched weapon, or died. Default: EndSpell(). */
	virtual void OnCastReleased();

	/** True while a sustained spell is running (the spellbook keeps a reference and blocks other casts). */
	virtual bool IsSustaining() const { return false; }

	const FGBSpellCast& GetCast() const { return Cast; }
	AActor* GetCaster() const { return Cast.Caster; }

	/** Fired once when the spell is over, just before the actor is destroyed. */
	FSimpleMulticastDelegate OnSpellEnded;

protected:
	/** Broadcasts OnSpellEnded and destroys the actor. Safe to call twice. */
	virtual void EndSpell();

	/** Finds the ground under a point (line trace down, world static). False if nothing within MaxDistance. */
	bool FindGround(const FVector& From, FVector& OutGround, float MaxDistance = 2000.f) const;

	UPROPERTY(VisibleAnywhere) TObjectPtr<USceneComponent> Root;

	UPROPERTY() FGBSpellCast Cast;
	bool bEnded = false;
};

