// Pure logic of the spell-casting quick-time event (GDD 7). No engine world needed: unit-tested.
#pragma once

#include "CoreMinimal.h"
#include "GBQTELogic.generated.h"

/** Part 1 inputs: W A S D on keyboard, the four face buttons on gamepad. */
UENUM(BlueprintType)
enum class EGBQTEKey : uint8
{
	Up,     // W / Triangle (Y)
	Left,   // A / Square (X)
	Down,   // S / Cross (A)
	Right   // D / Circle (B)
};

/** Part 2 gestures, drawn with the mouse or the right stick. Screen space: +X right, +Y down. */
UENUM(BlueprintType)
enum class EGBGesture : uint8
{
	LineRight,
	LineLeft,
	LineDown,
	LineUp,
	CircleClockwise,
	CircleCounterClockwise
};

UENUM(BlueprintType)
enum class EGBQTEPhase : uint8
{
	Inactive,
	Sequence,   // part 1 -> power
	Gesture,    // part 2 -> reach
	Finished
};

/** Outcome of one QTE. */
USTRUCT(BlueprintType)
struct GLYPHBOUND_API FGBQTEResult
{
	GENERATED_BODY()

	/** Part 1 score 0..1 = right steps / steps. */
	UPROPERTY() float Power = 0.f;
	/** Part 2 score 0..1 = average gesture score. */
	UPROPERTY() float Reach = 0.f;
	/** False when the QTE is off: the spell casts at its fixed default strength. */
	UPROPERTY() bool bUsedQTE = false;
	/** "The spell is cast if the player gets at least one step right" (always true when the QTE is off). */
	UPROPERTY() bool bSuccess = false;
	UPROPERTY() bool bTimedOut = false;
};

/** Numbers of one QTE run, read from QTE.json (through the player's stats, so gear can change them). */
struct GLYPHBOUND_API FGBQTEConfig
{
	int32 SequenceLength = 4;
	int32 GestureCount = 1;
	/** Real seconds for the whole QTE, both parts together. */
	float TimeLimit = 3.f;
	/** A gesture scoring below this counts as a missed step. */
	float GestureMinScore = 0.35f;
	/** Minimum path length (pixels, or stick units scaled by the component) before a gesture is judged. */
	float GestureMinLength = 120.f;
	/** Gestures that may be asked for. Empty = all. */
	TArray<EGBGesture> AllowedGestures;
};

/**
 * Scores how well a drawn path matches a gesture, 0..1. Rules that the tests pin down:
 *  - a straight stroke in the asked direction scores near 1; the opposite direction scores 0;
 *  - a full circle in the asked rotation scores near 1; the opposite rotation scores 0;
 *  - a path shorter than MinLength scores 0 (not judged yet).
 * Points are in screen space (+Y down); CircleClockwise is clockwise as seen on screen.
 */
struct GLYPHBOUND_API FGBGestureRecognizer
{
	static float Score(TConstArrayView<FVector2D> Points, EGBGesture Gesture, float MinLength);
	static float PathLength(TConstArrayView<FVector2D> Points);
	/** Signed total turning of the path in degrees; positive = clockwise on screen. */
	static float TotalTurnDegrees(TConstArrayView<FVector2D> Points);
};

/**
 * State machine of one QTE run. The component feeds it input and real time; the HUD reads it.
 *   Start -> phase Sequence: each key press consumes one step, right or wrong (a mistake lowers the result of its part)
 *         -> phase Gesture: points are accumulated; SubmitGesture() judges the current stroke as one step
 *         -> Finished when every step is consumed or the time limit runs out (unfinished steps count as missed).
 */
struct GLYPHBOUND_API FGBQTESession
{
	void Start(const FGBQTEConfig& InConfig, FRandomStream& Random);

	/** Part 1. Returns true if the key was the expected one. Ignored outside the Sequence phase. */
	bool PressKey(EGBQTEKey Key);

	/** Part 2. Adds a movement delta to the current stroke. Ignored outside the Gesture phase. */
	void AddGestureDelta(const FVector2D& Delta);
	/** Judges the current stroke as one gesture step and moves on. Returns its score. */
	float SubmitGesture();
	/** True once the current stroke is long enough to be judged (the component auto-submits when the input pauses or closes a circle). */
	bool IsGestureReadyToJudge() const;

	/** Advances real time. Finishes the session when the limit is reached. */
	void Advance(float RealDeltaSeconds);

	bool IsFinished() const { return Phase == EGBQTEPhase::Finished; }
	FGBQTEResult GetResult() const;

	// ---- Read by the HUD ----
	EGBQTEPhase Phase = EGBQTEPhase::Inactive;
	FGBQTEConfig Config;
	TArray<EGBQTEKey> Sequence;
	/** One entry per consumed step of part 1: was it right. */
	TArray<bool> SequenceResults;
	TArray<EGBGesture> Gestures;
	/** One entry per judged gesture: its score 0..1 (0 = missed). */
	TArray<float> GestureScores;
	/** The stroke being drawn, in accumulated screen units starting at (0,0). */
	TArray<FVector2D> CurrentStroke;
	float TimeElapsed = 0.f;
	bool bTimedOut = false;

	float GetTimeRemaining() const { return FMath::Max(0.f, Config.TimeLimit - TimeElapsed); }
};

// Runs the spell QTE on the player: slows time, routes input into FGBQTESession, reports the result.
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "QTE/GBQTELogic.h"
#include "GBQTEComponent.generated.h"

DECLARE_DELEGATE_OneParam(FGBOnQTEFinished, const FGBQTEResult& /*Result*/);

/**
 * GDD 7 requirements handled here:
 *  - time slows to the QTE.TimeDilation stat (read through the owner's UGBStatsComponent, so gear can change it);
 *  - the 3 s limit (QTE.TimeLimit) is real time and covers both parts;
 *  - it can be switched off (QTE.json "bEnabled": false, or console "gb.QTE 0"): StartQTE then finishes at once
 *    with bUsedQTE = false and the spell casts at its default strength.
 * The player character asks IsActive() to lock the camera, hold the last movement input and send
 * W/A/S/D + mouse / face buttons + right stick here instead of to movement and look.
 */
UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBQTEComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBQTEComponent();

	/** Starts a QTE for SpellId. OnFinished fires exactly once (possibly before this returns, when the QTE is off). Returns false if one is already running. */
	bool StartQTE(FName SpellId, FGBOnQTEFinished OnFinished);

	/** Ends the running QTE now; unfinished steps count as missed (death, cutscene). */
	void CancelQTE();

	bool IsActive() const { return bActive; }
	bool IsEnabled() const;
	FName GetSpellId() const { return ActiveSpellId; }

	// ---- Input (from the player character) ----
	void HandleKey(EGBQTEKey Key);
	/** Mouse delta in pixels, or right-stick value * a per-second scale, for part 2. */
	void HandleGestureInput(const FVector2D& Delta);

	/** The running session, for the HUD. Only meaningful while IsActive(). */
	const FGBQTESession& GetSession() const { return Session; }

	virtual void TickComponent(float DeltaTime, ELevelTick TickType, FActorComponentTickFunction* ThisTickFunction) override;

protected:
	virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

	void Finish();

	FGBQTESession Session;
	FGBOnQTEFinished FinishedDelegate;
	FName ActiveSpellId = NAME_None;
	bool bActive = false;
	/** Real seconds without gesture input, to auto-submit a stroke when the hand pauses. */
	float GestureIdleTime = 0.f;
	FRandomStream Random;
};

// Which era the world is in, and the travel between eras (fade out, swap, fade in).
#pragma once

#include "CoreMinimal.h"
#include "Subsystems/WorldSubsystem.h"
#include "Core/GBTypes.h"
#include "GBEraSubsystem.generated.h"

DECLARE_MULTICAST_DELEGATE_OneParam(FGBOnEraChanged, EGBEra /*NewEra*/);

/**
 * One map, two times (GDD 4). The swap is done two ways at once, so level design can use either:
 *  - actors with a UGBEraComponent appear / disappear with their era;
 *  - streaming sub-levels whose package name ends in "_Past" or "_Future" are shown / hidden with their era.
 * Travel is a fade (Game.json: EraFadeOutTime, EraHoldTime, EraFadeInTime) that hides the swap: the era changes
 * while the screen is fully covered. On arrival everything of the player is restored (health, mana, ammo) and a
 * checkpoint is saved: portals are the safe points of the map.
 */
UCLASS()
class GLYPHBOUND_API UGBEraSubsystem : public UTickableWorldSubsystem
{
	GENERATED_BODY()

public:
	static UGBEraSubsystem* Get(const UObject* WorldContextObject);

	EGBEra GetCurrentEra() const { return CurrentEra; }

	/** Changes era at once, no fade (level start, checkpoint restore). Broadcasts OnEraChanged. */
	void SetEraImmediate(EGBEra NewEra);

	/**
	 * Starts the travel fade to TargetEra. If bTeleport, the traveller is moved to Destination while the screen
	 * is covered. Returns false if a travel is already running.
	 */
	bool RequestTravel(EGBEra TargetEra, AActor* Traveller, bool bTeleport = false, const FTransform& Destination = FTransform::Identity);

	bool IsTravelling() const { return bTravelling; }

	/** 0 = clear, 1 = screen fully covered. The HUD draws it. */
	float GetFadeAlpha() const { return FadeAlpha; }

	/** True if something with this presence exists in Era. */
	static bool IsPresentIn(EGBEraPresence Presence, EGBEra Era);
	static EGBEra OtherEra(EGBEra Era) { return Era == EGBEra::Past ? EGBEra::Future : EGBEra::Past; }

	/** Fired after the swap (actors and sub-levels already updated), with the screen still covered when travelling. */
	FGBOnEraChanged OnEraChanged;
	/** Fired when a travel has fully finished (fade in done). */
	FGBOnEraChanged OnTravelFinished;

	// UTickableWorldSubsystem
	virtual void Tick(float DeltaTime) override;
	virtual TStatId GetStatId() const override;
	virtual bool DoesSupportWorldType(const EWorldType::Type WorldType) const override;

protected:
	void ApplyEra();

	EGBEra CurrentEra = EGBEra::Past;
	bool bTravelling = false;
	float FadeAlpha = 0.f;
	/** 0 fading out, 1 holding, 2 fading in. */
	int32 TravelStage = 0;
	float StageTime = 0.f;
	EGBEra PendingEra = EGBEra::Past;
	TWeakObjectPtr<AActor> PendingTraveller;
	bool bPendingTeleport = false;
	FTransform PendingDestination;
};

// Put it on any actor that exists in only one era, or that depends on a progress flag.
#pragma once

#include "CoreMinimal.h"
#include "Components/ActorComponent.h"
#include "Core/GBTypes.h"
#include "GBEraComponent.generated.h"

/**
 * Decides whether its owner is "present": visible, colliding and ticking. Present when ALL of these hold:
 *  - the current era matches Presence;
 *  - RequiredFlag is empty or set   (cross-era unlock: "open in the future because of what was done in the past");
 *  - RemovedByFlag is empty or not set (a barrier that disappears once something is done).
 * Era-gated zones (GDD 4) are built with this: a wall that is PastOnly, a bridge that is FutureOnly and
 * requires the flag set by a past encounter, etc. Flags live in UGBProgressSubsystem.
 */
UCLASS(ClassGroup = (Glyphbound), meta = (BlueprintSpawnableComponent))
class GLYPHBOUND_API UGBEraComponent : public UActorComponent
{
	GENERATED_BODY()

public:
	UGBEraComponent();

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Era")
	EGBEraPresence Presence = EGBEraPresence::Both;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Era")
	FName RequiredFlag = NAME_None;

	UPROPERTY(EditAnywhere, BlueprintReadWrite, Category = "Glyphbound|Era")
	FName RemovedByFlag = NAME_None;

	/** For actors spawned at runtime: set the fields, then call this. */
	void Configure(EGBEraPresence InPresence, FName InRequiredFlag = NAME_None, FName InRemovedByFlag = NAME_None);

	bool IsPresent() const { return bPresent; }

	/** Re-evaluates and applies (called on era change and flag change). */
	void Refresh();

	/** Pure rule, also used by the tests. */
	static bool ComputePresent(EGBEraPresence Presence, EGBEra CurrentEra, bool bRequiredFlagOk, bool bRemovedFlagSet);

	/** Fired when presence flips, after it is applied. Enemies use it to pause their AI. */
	FSimpleMulticastDelegate OnPresenceChanged;

protected:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type EndPlayReason) override;

	void ApplyPresence(bool bNewPresent);

	bool bPresent = true;
	/** The owner's own collision / tick settings, remembered so presence can be restored exactly. */
	bool bSavedCollision = true;
	bool bSavedTick = true;
	bool bHasSaved = false;
};

