const fs=require('fs');const f='Design/GDD.md';let t=fs.readFileSync(f,'utf8');
const nl=t.includes('\r\n')?'\r\n':'\n';
const rep=(a,b)=>{ if(!t.includes(a)) {console.log('MISSING: '+a.slice(0,60)); return;} t=t.split(a).join(b); };
rep('> Status: **v0.12, 2026-11-12**','> Status: **v0.13, 2026-11-12**');
rep('## Changelog'+nl,'## Changelog'+nl+'- v0.13 (2026-11-12): architect\'s day-1 technical decisions recorded in 0.1 (C++ only, no GAS, JSON data, code-built test arena, canvas HUD); new section 18 lists every provisional rule and number the architect had to pick. Code structure in \`Design/ARCHITECTURE.md\`.'+nl);
rep('- **Code:** C++ suggested for the core systems (AI agents handle code better than Blueprint graphs), with data assets / data tables for tuning. Final call: the architect.',
'- **Code (decided by the architect, 2026-11-12):** C++ only, one module, no Blueprint graphs; structure in \`Design/ARCHITECTURE.md\`. **Unreal\'s Gameplay Ability System is not used**: a small stat-and-modifier system, one damage function and one status-effect component cover the same needs with far less setup.'+nl+'- **Tuning data (decided by the architect):** every gameplay number lives in text files, \`Glyphbound/Content/Data/*.json\` (spells, weapons, enemies, items, skills, player, QTE...). They ship as loose files: the owner can change numbers in a packaged build with a text editor, and \`gb.ReloadData\` in the console reloads them while playing. This replaces the data tables suggested earlier (git only carries text in this team, and AI agents edit text reliably).'+nl+'- **Test level (decided by the architect):** the day-1 test arena is built in code on the engine\'s empty map, so no binary map asset is needed yet. Real levels come later from the level designers.');
fs.writeFileSync(f,t);" && grep -n "v0.13" Design/GDD.md | head

